typedef int (*stage_fn)(struct msg *);

static const stage_fn detour_stages[] = { validate_schema, trace_dump };

int route(struct route_cfg *cfg, struct msg *m) {
    if (cfg->detour_enabled)            /* flipped by a control command */
        for (size_t i = 0; i < N; i++)
            detour_stages[i](m);        /* inspect / modify in place */
    return deliver(m);                  /* same destination on both legs */
}
